from __future__ import annotations

import csv
import json
import sys
from pathlib import Path
from typing import Iterable


class HarnessError(Exception):
    \"\"\"Raised when the harness cannot process inputs or write output.\"\"\"


def _log(stage: str, status: str, attempt: int) -> None:
    print(json.dumps({\"stage\": stage, \"status\": status, \"attempt\": attempt}, ensure_ascii=False), file=sys.stderr)


def _has_nonempty_id(record: dict) -> bool:
    for key, value in record.items():
        if str(key).strip().lower() == \"id\":
            return value is not None and str(value).strip() "'!= ""
    return False


def _read_csv(path: Path) -> Iterable[dict]:
    try:
        with path.open("r", encoding="utf-8-sig", newline="") as handle:
            yield from csv.DictReader(handle)
    except OSError as exc:
        raise HarnessError(f"failed to read CSV {path}: {exc}") from exc


def _read_jsonl(path: Path) -> Iterable[dict]:
    try:
        with path.open("r", encoding="utf-8-sig") as handle:
            for line_number, line in enumerate(handle, start=1):
                if not line.strip():
                    continue
                try:
                    value = json.loads(line)
                except json.JSONDecodeError as exc:
                    raise HarnessError(f"invalid JSONL {path}:{line_number}: {exc}") from exc
                yield value if isinstance(value, dict) else {}
    except OSError as exc:
        raise HarnessError(f"failed to read JSONL {path}: {exc}") from exc


def _read_records(path: Path) -> Iterable[dict]:
    suffix = path.suffix.lower()
    if suffix == ".csv":
        return _read_csv(path)
    if suffix == ".jsonl":
        return _read_jsonl(path)
    raise HarnessError(f"unsupported input file type: {path}")


def _parse_yaml_scalar(value: str):
    value = value.strip()
    if value in {"", "null", "Null", "NULL", "~"}:
        return None
    if value in {"true", "True", "TRUE"}:
        return True
    if value in {"false", "False", "FALSE"}:
        return False
    if (value.startswith('"'\"') and value.endswith('\"')) or (value.startswith(\"'\") and value.endswith(\"'\")):
        return value[1:-1]
    return value


def _load_yaml_config(path: Path) -> dict:
    data = {}
    try:
        lines = path.read_text(encoding=\"utf-8-sig\").splitlines()
    except OSError as exc:
        raise HarnessError(f\"failed to read config {path}: {exc}\") from exc

    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith(\"#\"):
            continue
        if \":\" not in stripped:
            raise HarnessError(f\"invalid YAML config {path}:{line_number}\")
        key, value = stripped.split(\":\", 1)
        data[key.strip()] = _parse_yaml_scalar(value)
    return data


def load_config(config_path=\"config/m2.json\") -> dict:
    path = Path(config_path)
    suffix = path.suffix.lower()
    try:
        if suffix == \".json\":
            with path.open(\"r\", encoding=\"utf-8-sig\") as handle:
                data = json.load(handle)
        elif suffix in {\".yaml\", \".yml\"}:
            data = _load_yaml_config(path)
        else:
            raise HarnessError(f\"unsupported config file type: {path}\")
    except json.JSONDecodeError as exc:
        raise HarnessError(f\"invalid JSON config {path}: {exc}\") from exc
    except OSError as exc:
        raise HarnessError(f\"failed to read config {path}: {exc}\") from exc

    if not isinstance(data, dict):
        raise HarnessError(f\"config must be an object: {path}\")
    return data


def _extract(input_files):
    records = []
    files = [str(item) for item in input_files]
    for file_name in files:
        for record in _read_records(Path(file_name)):
            records.append(record)
    return files, records


def _clean(records):
    processed_count = 0
    rejected_count = 0
    for record in records:
        if _has_nonempty_id(record):
            processed_count += 1
        else:
            rejected_count += 1
    return processed_count, rejected_count


def _write_report(report, output):
    if output is None:
        return
    output_path = Path(output)
    try:
        output_path.parent.mkdir(parents=True, exist_ok=True)
        with output_path.open(\"w\", encoding=\"utf-8\") as handle:
            json.dump(report, handle, ensure_ascii=False, indent=2)
            handle.write(\"\\n\")
    except OSError as exc:
        raise HarnessError(f\"failed to write report {output_path}: {exc}\") from exc


def _with_retry(stage: str, func, retry_counter, max_retries: int = 2):
    attempt = 1
    while True:
        _log(stage, \"start\", attempt)
        try:
            result = func()
        except HarnessError:
            _log(stage, \"retry\" if attempt <= max_retries else \"failed\", attempt)
            if attempt > max_retries:
                raise
            retry_counter[0] += 1
            attempt += 1
        else:
            _log(stage, \"success\", attempt)
            return result


def run_dag(input_files, output=None, config_path=\"config/m2.json\"):
    \"\"\"Run extract -> clean -> report and optionally write the JSON report.\"\"\"
    config = load_config(config_path)
    retry_counter = [0]

    files, records = _with_retry(\"extract\", lambda: _extract(input_files), retry_counter)
    processed_count, rejected_count = _with_retry(\"clean\", lambda: _clean(records), retry_counter)

    report = {
        \"processed_count\": processed_count,
        \"rejected_count\": rejected_count,
        \"retry_count\": retry_counter[0],
        \"source_files\": files,
    }
    if \"report_label\" in config:
        report[\"report_label\"] = config.get(\"report_label\")

    _with_retry(\"report\", lambda: _write_report(report, output), retry_counter)
    report[\"retry_count\"] = retry_counter[0]
    if output is not None and retry_counter[0]:
        _write_report(report, output)
    return report
